/* Herramienta Unificada de Consultas Fleet */
let fetch;
try {
    fetch = global.fetch || require('node-fetch');
} catch (e) {
    fetch = global.fetch;
}

// Obtener parametros de forma segura
const query = typeof $query !== 'undefined' ? $query : null;
const queries = typeof $queries !== 'undefined' ? $queries : null;
const descriptions = typeof $descriptions !== 'undefined' ? $descriptions : null;

// Detectar si es query individual o batch
const hasQuery = query && typeof query === 'string' && query.trim().length > 0;
const hasBatch = queries && (
    (Array.isArray(queries) && queries.length > 0) ||
    (typeof queries === 'string' && queries.trim().startsWith('['))
);

if (!hasQuery && !hasBatch) {
    return 'Error: Proporciona query (string) o queries (array).';
}

// Si es batch
if (hasBatch) {
    let queriesArr;
    try {
        queriesArr = typeof queries === 'string' ? JSON.parse(queries) : queries;
    } catch (e) {
        queriesArr = [queries];
    }

    let descs;
    try {
        descs = typeof descriptions === 'string' ? JSON.parse(descriptions) : (descriptions || []);
    } catch (e) {
        descs = [];
    }

    if (queriesArr.length > 4) {
        queriesArr = queriesArr.slice(0, 4);
        descs = descs.slice(0, 4);
    }

    const webhookUrl = 'http://n8n:5678/webhook/ejecutar-fleet-batch';
    const options = {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ queries: queriesArr, descriptions: descs })
    };

    try {
        const response = await fetch(webhookUrl, options);
        if (response.ok) {
            const data = await response.text();
            const safeData = data.length > 12000 ? data.substring(0, 12000) + '... [TRUNCADO]' : data;
            return 'Resultado Batch: ' + safeData;
        } else {
            const errorText = await response.text();
            return 'Error batch: ' + response.status + ' - ' + errorText;
        }
    } catch (error) {
        return 'Error conexión batch: ' + error.message;
    }
}

// Si es query individual
const webhookUrl = 'http://n8n:5678/webhook/ejecutar-fleet';
const options = {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: query, action: 'live_query' })
};

try {
    const response = await fetch(webhookUrl, options);
    if (response.ok) {
        const data = await response.text();
        const safeData = data.length > 8000 ? data.substring(0, 8000) + '... [TRUNCADO]' : data;
        return 'Resultado: ' + safeData;
    } else {
        const errorText = await response.text();
        return 'Error: ' + response.status + ' - ' + errorText;
    }
} catch (error) {
    return 'Error conexión: ' + error.message;
}
